-- 2.2: живой мир — NPC, 25 новых квестов по всему штату, больница изнутри, поезда, новые работы, рассрочка
ALTER TABLE quests ADD COLUMN giver TEXT DEFAULT '';
ALTER TABLE quests ADD COLUMN req_quest INTEGER DEFAULT 0;
ALTER TABLE quests ADD COLUMN req_level INTEGER DEFAULT 0;
ALTER TABLE quests ADD COLUMN city TEXT DEFAULT '';
ALTER TABLE quests ADD COLUMN descr TEXT DEFAULT '';
ALTER TABLE quest_steps ADD COLUMN say TEXT DEFAULT '';
ALTER TABLE accounts ADD COLUMN debt INTEGER DEFAULT 0;
CREATE TABLE IF NOT EXISTS npcs (code TEXT PRIMARY KEY, name TEXT, skin INTEGER, loc TEXT, anim TEXT DEFAULT '', greet TEXT DEFAULT '');
